#include<bits/stdc++.h>
using namespace std;

int main() {
    int m, n, p;

    // Input sizes
    cout << "Enter rows and columns of A: ";
    cin >> m >> n;  // A is m x n
    cout << "As B matrix's row number needs to be same as A matrix's column number.\nSo only enter columns of B: ";
    cin >> p;       // B is n x p

    // let ->>  A --> m × n  &  B -->> n × p
    // Product C = A*B -->> size will be -->> m × p ( m by p matrix)
    int A[m][n], B[n][p], C[m][p];

    // Input matrix A
    cout << "Enter elements of matrix A:\n";
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            cin >> A[i][j];

    // Input matrix B
    cout << "Enter elements of matrix B:\n";
    for (int i = 0; i < n; i++)
        for (int j = 0; j < p; j++)
            cin >> B[i][j];


    // Matrix multiplication
    // As Product C = A*B -->> size will be -->> m × p
    // So to store product matrix >> we used i & j >> for row & column c[i][j]
    // As A's column == B's row
    // A[i][k] to get A's column || B[k][j] to get B's row
    for (int i = 0; i < m; i++)
        for (int j = 0; j < p; j++)
            for (int k = 0; k < n; k++)
                C[i][j] += A[i][k] * B[k][j];


    // Output result
    cout << "Result matrix C:\n";
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            cout << C[i][j] << " ";
        }
        cout << endl;
    }

return 0;
}

